/// Trait that must be implemented by all types that can be inserted into Kinetica.
///
/// This trait is automatically implemented for all generated request types.
/// Custom record types must implement this to work with `BulkInserter`.
///
/// **Note**: Types implementing this trait must also implement `serde::Serialize`
/// for Avro encoding to work.
///
/// # Example (Using Builder API - Recommended)
///
/// ```
/// use gpudb_api::{KineticaRecord, AvroSchemaBuilder, AvroType, TypePropertiesBuilder, avro_schema};
/// use std::collections::HashMap;
///
/// #[derive(serde::Serialize, Clone, Default)]
/// struct MyRecord {
///     id: i32,
///     name: String,
/// }
///
/// impl KineticaRecord for MyRecord {
///     fn avro_schema(&self) -> &'static str {
///         avro_schema!(
///             AvroSchemaBuilder::new("MyRecord")
///                 .int_field("id")
///                 .string_field("name")
///         )
///     }
///
///     fn type_properties() -> HashMap<String, Vec<String>> {
///         TypePropertiesBuilder::new()
///             .primary_key("id")
///             .data("name")
///             .build()
///     }
/// }
/// ```
///
/// # Example (Manual JSON - Legacy)
///
/// ```
/// use gpudb_api::KineticaRecord;
/// use std::collections::HashMap;
///
/// #[derive(serde::Serialize, Clone, Default)]
/// struct MyRecord {
///     id: i32,
///     name: String,
/// }
///
/// impl KineticaRecord for MyRecord {
///     fn avro_schema(&self) -> &'static str {
///         r#"{"type":"record","name":"MyRecord","fields":[
///             {"name":"id","type":"int"},
///             {"name":"name","type":"string"}
///         ]}"#
///     }
///
///     fn type_properties() -> HashMap<String, Vec<String>> {
///         let mut m = HashMap::new();
///         m.insert("id".into(), vec!["int".into(), "primary_key".into()]);
///         m
///     }
/// }
/// ```
pub trait KineticaRecord: serde::Serialize {
    /// Returns the Avro schema as a JSON string for this record type.
    fn avro_schema(&self) -> &'static str;

    /// Returns type properties including field types and attributes (e.g., primary_key).
    fn type_properties() -> std::collections::HashMap<String, Vec<String>>;

    /// Whether requests of this type are Snappy-compressed when the client has
    /// [`KineticaOptions::use_snappy`] enabled.
    ///
    /// Compression is opt-in per endpoint, not global: only the endpoints that
    /// carry bulk record payloads pay the CPU cost of compressing, and the rest
    /// go out as `application/octet-stream`. The generator overrides this for
    /// `/insert/records` and `/update/records`; every other request type keeps
    /// the default.
    fn use_compression() -> bool {
        false
    }
}
